"""Vista HTML autocontenida para lectura en cualquier navegador, complementa PBIP."""
from pathlib import Path
import csv,json
ROOT=Path(__file__).resolve().parents[1]

def run():
    def load(p):
        with (ROOT/p).open() as f:
            rows=list(csv.DictReader(f))
        for row in rows:
            for k,v in row.items():
                try:row[k]=float(v)
                except ValueError:pass
        return rows
    data={k:load(p) for k,p in [('monitor','resultados/monitorizacion.csv'),
       ('policies','resultados/politicas.csv'),('crm','datos/crm.csv'),('portfolio','datos/cartera.csv')]}
    summary=json.loads((ROOT/'resultados/resumen.json').read_text())
    template='''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Nexo Crédito | Grupo 6</title><style>
:root{--ink:#142b36;--teal:#087f8c;--line:#dce5e9;--muted:#5d717b;--red:#b74b40}*{box-sizing:border-box}body{margin:0;background:#f3f6f8;color:var(--ink);font:15px system-ui,sans-serif}header{background:var(--ink);color:white;padding:28px 5%;display:flex;justify-content:space-between;align-items:center}h1{font-size:28px;letter-spacing:-1px;margin:0 0 6px}header p{color:#b8d2da;margin:0}.tag{font-size:12px;border:1px solid #62818d;border-radius:25px;padding:8px 12px}main{max-width:1440px;margin:auto;padding:28px 4%}nav{display:flex;gap:6px;border-bottom:1px solid var(--line);padding-bottom:16px;align-items:center}button{border:0;background:transparent;padding:12px 20px;font:inherit;color:var(--muted);border-radius:6px;cursor:pointer}button.active{background:var(--teal);color:white}select{margin-left:auto;padding:12px;border:1px solid var(--line);border-radius:6px;background:white;color:var(--ink)}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin:24px 0}.card,.panel{background:white;border:1px solid var(--line);border-radius:10px;padding:22px}.card small{display:block;color:var(--muted);margin-bottom:12px}.card strong{font-size:29px;letter-spacing:-1px}.card span{display:block;font-size:12px;color:var(--muted);margin-top:8px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.panel h3{font-size:17px;margin:0 0 20px}.panel p{line-height:1.6;color:var(--muted)}.callout{border-left:4px solid var(--teal);padding:16px 20px;background:#e4f3f4;margin:22px 0;line-height:1.6}.callout.risk{border-color:var(--red);background:#fff0ec}svg{width:100%;height:auto}table{border-collapse:collapse;width:100%;font-size:13px}td,th{text-align:right;border-bottom:1px solid var(--line);padding:12px 9px}td:first-child,th:first-child{text-align:left}th{color:var(--muted)}footer{margin:25px 0;color:var(--muted);font-size:12px;line-height:1.8}.bsc{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.bsc div{padding:18px;border-radius:8px;background:#f3f6f8;border-top:3px solid var(--teal)}.bsc strong{display:block;margin-bottom:8px}@media(max-width:850px){.cards,.bsc{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}nav{flex-wrap:wrap}select{margin-left:0}header{gap:20px}}</style>
<header><div><h1>NEXO CRÉDITO</h1><p>Crecer sin perder el control del riesgo</p></div><span class="tag">GRUPO 6 · DATOS SINTÉTICOS</span></header>
<main><nav><button class="active" data-tab="direccion">Dirección</button><button data-tab="mlops">MLOps y riesgo</button><button data-tab="crm">CRM y BSC</button><button data-tab="crisis">Comparar políticas</button><select id="cohort" aria-label="Seleccionar cohorte"><option value="all">Todas las cohortes</option>@@OPTIONS@@</select></nav><div id="content"></div><footer>Grupo 6 · Daniel Llopis Conejo · Juan Sebastián Roman Herrera · Nicolás Rodríguez Oicatá · Andrés Fabricio Cabrera Torres<br>Evaluación histórica con resultados a 12 meses. Cartera: saldo vivo a 30/06/2025. Las métricas API del escenario son objetivos simulados; la prueba HTTP local se documenta por separado.</footer></main>
<script>const D=@@DATA@@,S=@@SUMMARY@@;let tab='direccion';const $=s=>document.querySelector(s),fmt=(n,d=2)=>new Intl.NumberFormat('es-ES',{maximumFractionDigits:d,minimumFractionDigits:d}).format(n),pct=n=>fmt(n*100)+' %',eur=n=>fmt(n,0)+' €',sum=(a,k)=>a.reduce((s,x)=>s+x[k],0),avg=(a,k)=>a.length?sum(a,k)/a.length:0;
const filter=a=>a.filter(x=>$('#cohort').value==='all'||x.cohort===$('#cohort').value);
const card=(label,value,note)=>`<div class="card"><small>${label}</small><strong>${value}</strong><span>${note}</span></div>`;
function graph(rows,keys,labels,percent=false){const W=560,H=240,L=48,R=16,T=18,B=36;let max=Math.max(...rows.flatMap(r=>keys.map(k=>r[k])),.01)*1.18;const xx=i=>L+i*(W-L-R)/Math.max(rows.length-1,1),yy=v=>H-B-(H-T-B)*v/max;let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${labels.join(' y ')}">`;
for(let j=0;j<=4;j++){let v=max*j/4,y=yy(v);svg+=`<line x1="${L}" x2="${W-R}" y1="${y}" y2="${y}" stroke="#e4ebef"/><text x="${L-8}" y="${y+4}" text-anchor="end" font-size="11" fill="#5d717b">${percent?fmt(v*100,0)+'%':fmt(v,2)}</text>`}keys.forEach((k,j)=>{const col=['#087f8c','#b74b40'][j];svg+=`<polyline fill="none" stroke="${col}" stroke-width="3" points="${rows.map((r,i)=>xx(i)+','+yy(r[k])).join(' ')}"/>`;rows.forEach((r,i)=>{svg+=`<circle cx="${xx(i)}" cy="${yy(r[k])}" r="4" fill="${col}"><title>${r.cohort}: ${fmt(r[k],4)}</title></circle>`})});rows.forEach((r,i)=>svg+=`<text x="${xx(i)}" y="${H-10}" text-anchor="middle" font-size="11" fill="#5d717b">${r.cohort.slice(5)}</text>`);return svg+'</svg><p style="font-size:12px">'+labels.join(' · ')+'</p>'}
function table(rows,fields,headers,formats){return '<table><thead><tr>'+headers.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+fields.map((k,i)=>'<td>'+(formats[i]?formats[i](r[k]):r[k])+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}
function render(){let mon=filter(D.monitor),crm=filter(D.crm),port=filter(D.portfolio),pol=filter(D.policies);let html='';
if(tab==='direccion'){html='<div class="cards">'+card('Saldo vivo',eur(sum(port,'balance')),'Corte común: 30/06/2025')+card('NPL sobre saldo',pct(sum(port,'npl_balance')/sum(port,'balance')),'Stock; no es default acumulado')+card('Churn mensual medio',pct(sum(crm,'churned')/sum(crm,'active_start')),'Ponderado por clientes-mes')+card('Solicitudes',fmt(sum(mon,'n'),0),'Cohortes de 2024')+'</div><div class="grid"><section class="panel"><h3>La cartera cambia de perfil</h3>'+graph(mon,['default_rate','mean_pd'],['Impago observado 12m','PD media'],true)+'</section><section class="panel"><h3>Monitorización de la calibración</h3>'+graph(mon,['oe'],['Observado / esperado'])+'</section></div><div class="callout risk"><strong>Decisión:</strong> la captación continúa bajo revisión reforzada. El modelo vigente ordena mejor el riesgo, pero infravalora su magnitud tras el cambio de abril.</div>'}
if(tab==='mlops'){html='<div class="cards">'+card('AUC medio',fmt(avg(mon,'auc'),3),'Discriminación por cohorte')+card('Brier medio',fmt(avg(mon,'brier'),3),'Menor es mejor; depende de población')+card('O/E medio',fmt(avg(mon,'oe'),2),'Referencia de revisión: 0,80–1,25')+card('PSI medio',fmt(avg(mon,'psi_score'),3),'No detecta toda deriva de concepto')+'</div><div class="grid"><section class="panel"><h3>Cambio de población</h3>'+graph(mon,['psi_score'],['PSI de la distribución del score'])+'</section><section class="panel"><h3>AUC y error probabilístico</h3>'+graph(mon,['auc','brier'],['AUC','Brier'])+'</section></div><section class="panel">'+table(mon,['cohort','auc','brier','oe','psi_score','alert'],['Cohorte','AUC','Brier','O/E','PSI','Estado'],[null,x=>fmt(x,3),x=>fmt(x,3),x=>fmt(x,2),x=>fmt(x,3),null])+'</section><div class="callout">El cambio de población de marzo abre una revisión. La deriva de concepto de abril requiere etiquetas maduradas: PSI bajo no equivale a modelo sano.</div>'}
if(tab==='crm'){html='<div class="cards">'+card('Conversión',pct(sum(crm,'conversions')/sum(crm,'contacted')),'Conversiones / contactos únicos')+card('Resolución en SLA',pct(sum(crm,'resolved_sla')/sum(crm,'tickets')),'Atención omnicanal')+card('Coste por conversión',eur(sum(crm,'campaign_cost')/sum(crm,'conversions')),'Coste directo de campaña')+card('Cobertura formativa',pct(sum(crm,'trained')/sum(crm,'staff')),'Escenario de recursos')+'</div><section class="panel"><h3>Mapa estratégico CRM</h3><div class="bsc"><div><strong>Aprendizaje</strong>Formación y responsabilidades claras</div><div><strong>Procesos</strong>Respuesta coherente y dato trazable</div><div><strong>Clientes</strong>Retención y servicio por segmento</div><div><strong>Finanzas</strong>Margen ajustado al riesgo</div></div><p>La relación causal es una hipótesis de gestión. Las conversiones observadas no acreditan el efecto incremental de una campaña.</p></section><section class="panel" style="margin-top:20px">'+table(crm,['cohort','segment','channel','active_start','churned','conversions'],['Mes','Segmento','Canal principal','Activos inicio','Bajas','Conversiones'],[null,null,null,x=>fmt(x,0),x=>fmt(x,0),x=>fmt(x,0)])+'</section>'}
if(tab==='crisis'){html='<div class="callout"><strong>Comparación controlada.</strong> Selecciona junio para ver el holdout que no intervino en entrenamiento ni selección. La contención es una política temporal; el candidato es otro modelo.</div><section class="panel"><h3>Impacto económico de las políticas</h3>'+table(pol,['cohort','policy','approved','bad_rate','realized_loss','realized_margin'],['Cohorte','Política','Propuestas','Impago 12m','Pérdida observada','Margen observado'],[null,null,x=>fmt(x,0),pct,eur,eur])+'</section><div class="grid" style="margin-top:20px"><section class="panel"><h3>Contener sin fingir una reparación</h3><p>El hotfix deriva a revisión la zona DTI &gt; 0,28 y utilización &gt; 0,50. No cambia los coeficientes ni elimina solicitudes del historial.</p></section><section class="panel"><h3>Reentrenar con una puerta de salida</h3><p>El candidato incorpora una interacción no lineal. Se selecciona con mayo y se contrasta con junio, manteniendo separadas calibración, aprobación y margen.</p></section></div>'}
$('#content').innerHTML=html;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab))}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;if(tab==='crisis'&&$('#cohort').value==='all')$('#cohort').value='2024-06';render()});$('#cohort').onchange=render;render();</script></html>'''
    options=''.join(f'<option value="2024-{i:02}">2024-{i:02}</option>' for i in range(1,7))
    html=template.replace('@@OPTIONS@@',options).replace('@@DATA@@',json.dumps(data,ensure_ascii=False)).replace('@@SUMMARY@@',json.dumps(summary,ensure_ascii=False))
    (ROOT/'dashboard.html').write_text(html,encoding='utf-8')
    print('Dashboard HTML autocontenido generado')

if __name__=='__main__':run()
